# Embeds the translation tables in the executable.
# Usage: python3 tools/make_i18n.py   (from the repository root)
# Reads resources/i18n/pt-BR.txt and writes src/ui/I18nData.h.
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
tables = [("ptBR", "resources/i18n/pt-BR.txt")]

out = ["#pragma once", "",
       "// Generated by tools/make_i18n.py from resources/i18n/*.txt - do not edit by hand.", "",
       "namespace lynx::i18n::data", "{"]
for name, path in tables:
    data = (root / path).read_bytes()
    out.append(f"// {path}")
    out.append(f"inline constexpr unsigned char {name}[] = {{")
    for i in range(0, len(data), 24):
        out.append(", ".join(str(b) for b in data[i:i + 24]) + ",")
    out.append("};")
out.append("} // namespace lynx::i18n::data")
out.append("")
(root / "src/ui/I18nData.h").write_text("\n".join(out))
